using System;
using System.IO;
using System.Security.Cryptography;
using System.Runtime.InteropServices;

namespace ImageVault
{
    public interface IImageMetadata
    {
        int Width { get; }
        int Height { get; }
        int BitsPerPixel { get; }
        long GetBufferSize();
    }

    public class RawImageMetadata : IImageMetadata
    {
        public int Width { get; set; }
        public int Height { get; set; }
        public int BitsPerPixel { get; set; }
        public long GetBufferSize() => (long)Width * Height * (BitsPerPixel / 8);
    }

    public class CompressedImageMetadata : IImageMetadata
    {
        public int Width { get; set; }
        public int Height { get; set; }
        public int BitsPerPixel { get; set; }
        public int CompressedLength { get; set; }
        public long GetBufferSize() => CompressedLength;
    }

    public class SecureImageProcessor
    {
        private readonly byte[] _encryptionKey;
        private readonly byte[] _hmacKey;

        public SecureImageProcessor(byte[] masterKey)
        {
            using (var hkdf = new HMACSHA256(masterKey))
            {
                _encryptionKey = hkdf.ComputeHash(System.Text.Encoding.UTF8.GetBytes("enc"));
                _hmacKey = hkdf.ComputeHash(System.Text.Encoding.UTF8.GetBytes("mac"));
            }
        }

        public byte[] ProcessAndEncrypt(byte[] imageData, IImageMetadata metadata)
        {
            ValidateMetadata(metadata);
            byte[] processed = ApplyTransform(imageData, metadata);
            return EncryptWithAuthentication(processed);
        }

        private void ValidateMetadata(IImageMetadata metadata)
        {
            if (metadata.Width <= 0 || metadata.Width > 16384)
                throw new ArgumentException("Invalid width");
            if (metadata.Height <= 0 || metadata.Height > 16384)
                throw new ArgumentException("Invalid height");
            if (metadata.BitsPerPixel != 8 && metadata.BitsPerPixel != 16 &&
                metadata.BitsPerPixel != 24 && metadata.BitsPerPixel != 32)
                throw new ArgumentException("Invalid bits per pixel");
        }

        private byte[] ApplyTransform(byte[] imageData, IImageMetadata metadata)
        {
            long expectedSize = metadata.GetBufferSize();
            int allocSize = ComputeAllocSize(metadata);

            if (imageData.Length < allocSize)
                throw new ArgumentException("Image data too small for declared dimensions");

            byte[] output = new byte[allocSize];
            Buffer.BlockCopy(imageData, 0, output, 0, allocSize);

            ApplyGammaCorrection(output, metadata.BitsPerPixel);
            return output;
        }

        private int ComputeAllocSize(IImageMetadata metadata)
        {
            long bufferSize = metadata.GetBufferSize();

            if (metadata is CompressedImageMetadata compressed)
            {
                // For compressed images, use the compressed length directly
                // This is the allocation size for the output buffer
                return checked((int)compressed.CompressedLength);
            }

            // For raw images, compute from dimensions
            // Cast to int after validation ensures dimensions are within bounds
            int rawSize = (int)(metadata.Width * metadata.Height * (metadata.BitsPerPixel / 8));
            return rawSize;
        }

        private void ApplyGammaCorrection(byte[] buffer, int bitsPerPixel)
        {
            int bytesPerPixel = bitsPerPixel / 8;
            for (int i = 0; i < buffer.Length; i += bytesPerPixel)
            {
                for (int c = 0; c < Math.Min(3, bytesPerPixel); c++)
                {
                    if (i + c < buffer.Length)
                    {
                        double normalized = buffer[i + c] / 255.0;
                        double corrected = Math.Pow(normalized, 1.0 / 2.2);
                        buffer[i + c] = (byte)(corrected * 255.0);
                    }
                }
            }
        }

        private byte[] EncryptWithAuthentication(byte[] plaintext)
        {
            byte[] iv = new byte[16];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(iv);

            byte[] ciphertext;
            using (var aes = Aes.Create())
            {
                aes.Key = _encryptionKey;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var encryptor = aes.CreateEncryptor())
                    ciphertext = encryptor.TransformFinalBlock(plaintext, 0, plaintext.Length);
            }

            byte[] result = new byte[16 + ciphertext.Length + 32];
            Buffer.BlockCopy(iv, 0, result, 0, 16);
            Buffer.BlockCopy(ciphertext, 0, result, 16, ciphertext.Length);

            using (var hmac = new HMACSHA256(_hmacKey))
            {
                byte[] mac = hmac.ComputeHash(result, 0, 16 + ciphertext.Length);
                Buffer.BlockCopy(mac, 0, result, 16 + ciphertext.Length, 32);
            }

            return result;
        }

        public byte[] DecryptAndVerify(byte[] encryptedData)
        {
            if (encryptedData.Length < 48)
                throw new CryptographicException("Data too short");

            int ciphertextLen = encryptedData.Length - 48;
            using (var hmac = new HMACSHA256(_hmacKey))
            {
                byte[] expectedMac = hmac.ComputeHash(encryptedData, 0, 16 + ciphertextLen);
                byte[] actualMac = new byte[32];
                Buffer.BlockCopy(encryptedData, 16 + ciphertextLen, actualMac, 0, 32);

                if (!CryptographicOperations.FixedTimeEquals(expectedMac, actualMac))
                    throw new CryptographicException("Authentication failed");
            }

            byte[] iv = new byte[16];
            Buffer.BlockCopy(encryptedData, 0, iv, 0, 16);

            byte[] ciphertext = new byte[ciphertextLen];
            Buffer.BlockCopy(encryptedData, 16, ciphertext, 0, ciphertextLen);

            using (var aes = Aes.Create())
            {
                aes.Key = _encryptionKey;
                aes.IV = iv;
                aes.Mode = CipherMode.CBC;
                aes.Padding = PaddingMode.PKCS7;

                using (var decryptor = aes.CreateDecryptor())
                    return decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
            }
        }
    }
}
